import java.lang.reflect.*; import java.util.*;
/** Minimal runner: runs every public @org.junit.Test method; prints one line per test and a summary. */
public class HostJUnitRunner { public static void main(String[] a) throws Exception { int pass=0,fail=0; for(String cn:a){Class<?> c=Class.forName(cn); for(Method m:c.getMethods()){org.junit.Test t=m.getAnnotation(org.junit.Test.class); if(t==null)continue; Object o=c.getDeclaredConstructor().newInstance(); long st=System.nanoTime(); try{m.invoke(o); if(t.expected()!=org.junit.Test.None.class){fail++;System.out.println("FAIL "+cn+"."+m.getName()+" expected "+t.expected().getSimpleName());continue;} pass++;System.out.printf("PASS %s.%s %dms%n",cn,m.getName(),(System.nanoTime()-st)/1000000);}catch(InvocationTargetException e){Throwable x=e.getCause(); if(t.expected().isInstance(x)){pass++;System.out.printf("PASS %s.%s (expected %s)%n",cn,m.getName(),x.getClass().getSimpleName());} else {fail++;System.out.println("FAIL "+cn+"."+m.getName()+" "+x);}}}} System.out.println("SUMMARY pass="+pass+" fail="+fail); System.exit(fail==0?0:1);} }
